vulnerable_code:
app.post('/api/comments/:commentId/delete', async (req, res) => {
  await db.Comment.destroy({ where: { id: req.params.commentId } });
  res.send('Comment deleted');
});

corrected_code:
app.post('/api/comments/:commentId/delete', async (req, res) => {
  const comment = await db.Comment.findByPk(req.params.commentId);
  if (!comment || comment.authorId !== req.user.id) return res.status(403).send('Forbidden');
  await comment.destroy();
  res.send('Comment deleted');
});
